              someCode()
          }
      }

在应用快速修复后：


      fun foo(arg: Boolean): Int {
          if (arg) return 0
          someCode()
      }

Inspection ID: RedundantElseInIf

fullDescription.text:
报告可以替换为索引运算符 ('[]') 的 'map.put' 函数调用。 使用语法糖可使代码更简单。 该快速修复会将 'put' 调用替换为赋值。 示例： 'fun foo(map: MutableMap<Int, String>) {
      map.put(42, "foo")
  }' 在应用快速修复后： 'fun foo(map: MutableMap<Int, String>) {
      map[42] = "foo"
  }' Inspection ID: ReplacePutWithAssignment

